target.css:
:root {
  --ink: #243447;
  --paper: #fffdf7;
  --line: #d9e1df;
  --mint: #dff3ea;
  --mint-ink: #176b55;
  --coral: #f06c57;
}

.tool-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
}

.card-header {
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--mint-ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.card-header h1,
.tool-row h2 {
  margin: 0;
  font-size: 18px;
  line-height: 1.15;
}

.status {
  border-radius: 999px;
  background: var(--coral);
  color: var(--paper);
  padding: 5px 9px;
  font-size: 12px;
  font-weight: 700;
}

.tool-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
}

.tool-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 10px;
  background: var(--mint);
  font-size: 22px;
}

.tool-row p {
  margin: 4px 0 0;
  font-size: 14px;
}

.card-footer {
  border-top: 1px solid var(--line);
  color: var(--mint-ink);
  font-size: 13px;
  font-weight: 700;
}

.card-footer button {
  border: 0;
  border-radius: 7px;
  background: var(--ink);
  color: var(--paper);
  padding: 8px 11px;
  font: inherit;
  cursor: pointer;
}
